32|   /** Capacity after club bookings: halved if one half is taken, zero if the whole rink is. */
33|   effectiveCapacity(session: Session): number {
34|     const overlapping = this.clubBookings
35|       .findByDate(session.date)
36|       .filter((c) => c.start < session.end && session.start < c.end);
37|     if (overlapping.some((c) => c.area === "whole")) return 0;
38|     const halvesTaken = new Set(overlapping.map((c) => c.area)).size;
39|     if (halvesTaken >= 2) return 0;
40|     if (halvesTaken === 1) return Math.floor(session.capacity / 2);
41|     return session.capacity;
42|   }
