44|   create(input: NewSession): Session {
45|     if (!DATE.test(input.date) || Number.isNaN(Date.parse(input.date)))
46|       throw new DomainError(400, "date must be YYYY-MM-DD");
47|     if (!TIME.test(input.start) || !TIME.test(input.end))
48|       throw new DomainError(400, "start and end must be HH:MM");
49|     if (input.end <= input.start) throw new DomainError(400, "end must be after start");
50|     if (!Number.isInteger(input.capacity) || input.capacity < 1)
51|       throw new DomainError(400, "capacity must be a positive integer");
52|     if (!Number.isInteger(input.priceCents) || input.priceCents < 0)
53|       throw new DomainError(400, "priceCents must be a non-negative integer");
